window.suShiJourneyWorks = [{"work_id":"nanxing_work_001","title":"郭纶","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_03_lingyun_buddha","location_text":"嘉州一带","summary":"见河西老兵郭纶，写其战功不赏、沉沦小官。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"〈（纶本河西弓箭手，屡战有功，不赏。自黎州都监官满，贫不能归。今权嘉州监税。）〉\n河西猛士无人识，日暮津亭阅过船。\n路人但觉骢马瘦，不知铁槊大如椽。\n因言西方久不战，截发愿作万骑先。\n我当凭轼与寓目，看君飞矢射蛮毡。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E9%83%AD%E7%B6%B8_%28%E8%98%87%E8%BB%BE%29","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_002","title":"初发嘉州","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_03_lingyun_buddha","location_text":"嘉州 / 乐山","summary":"离嘉州启舟，船过凌云大佛脚下，写离乡和江山开阔。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"朝发鼓阗阗，西风猎画旃。\n故乡飘已远，往意浩无边。\n锦水细不见，蛮江清更鲜。\n奔腾过佛脚，旷荡造平川。\n野市有禅客，钓台寻暮烟。\n相期定先到，久立水潺潺。","text_scope":"full_page","text_source_label":"诗歌库《苏轼诗全集》","text_source_url":"https://www.shigeku.org/xlib/lingshidao/gushi/sushi3.htm","text_status":"local","text_status_note":"公开文本已接入；此条为补充来源，必须与可靠点校本复核"},{"work_id":"nanxing_work_003","title":"犍为王氏书楼","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_03_lingyun_buddha","location_text":"犍为","summary":"过王氏旧书楼，借藏书楼兴废写人事零落。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"树林幽翠满山谷，楼观突兀起江滨。\n云是昔人藏书处，磊落万卷今生尘。\n江边日出红雾散，绮窗画阁青氛氲。\n山猿悲啸谷泉响，野鸟嘐戛岩花春。\n借问主人今何在，被甲远戍长苦辛。\n先登搏战事斩级，区区何者为三坟。\n书生古亦有战阵，葛巾羽扇挥三军。\n古人不见悲世俗，回首苍山空白云。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E7%8A%8D%E7%82%BA%E7%8E%8B%E6%B0%8F%E6%9B%B8%E6%A8%93","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_004","title":"过宜宾见夷中乱山","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_04_rongzhou_yibin","location_text":"宜宾、戎州附近","summary":"过川南夷汉交界山地，写乱山、蛮荒和隐逸念头。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"江寒晴不知，远见山上日。\n朦胧含高峰，晃荡射峭壁。\n横云忽飘散，翠树纷历历。\n行人挹孤光，飞鸟投远碧。\n蛮荒谁复爱，秾秀安可适。\n岂无避世士，高隐炼精魄。\n谁能从之游，路有豺虎迹。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E9%81%8E%E5%AE%9C%E8%B3%93%E8%A6%8B%E5%A4%B7%E4%B8%AD%E4%BA%82%E5%B1%B1_%28%E8%98%87%E8%BB%BE%29","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_005","title":"夜泊牛口","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_05_niukou","location_text":"牛口","summary":"夜泊江岸，见贫苦人家，写边地小民衣食艰难。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"日落红雾生，系舟宿牛口。\n居民偶相聚，三四依古柳。\n负薪出深谷，见客喜且售。\n煮蔬为夜餐，安识肉与酒。\n朔风吹茅屋，破壁见星斗。\n儿女自咿嚘，亦足乐且久。\n人生本无事，苦为世味诱。\n富贵耀吾前，贫贱独难守。\n谁知深山子，甘与麋鹿友。\n置身落蛮荒，生意不自陋。\n今予独何者，汲汲强奔走。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E5%A4%9C%E6%B3%8A%E7%89%9B%E5%8F%A3_%28%E8%98%87%E8%BB%BE%29","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_006","title":"牛口见月","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_05_niukou","location_text":"牛口","summary":"夜起看月，由江上月色联想到汴京水灾旧忆。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"掩窗寂已睡，月脚垂孤光。\n披衣起周览，飞露洒我裳。\n山川同一色，浩若涉大荒。\n幽怀耿不寐，四顾独仿徨。\n忽忆丙申年，京邑大雨滂。\n蔡河中夜决，横浸国南方。\n车马无复见，纷纷操筏郎。\n新秋忽已晴，九陌尚汪洋。\n龙津观夜市，灯火亦煌煌。\n新月皎如昼，疏星弄寒芒。\n不知京国喧，是谓江湖乡。\n今来牛口渚，见月重凄凉。\n却思旧游处，满陌沙尘黄。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E7%89%9B%E5%8F%A3%E8%A6%8B%E6%9C%88","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_007","title":"戎州","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_04_rongzhou_yibin","location_text":"戎州，今宜宾一带","summary":"写川南边地市易、夷汉往来和山城风土。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"乱山围古郡，市易带群蛮。\n庾岭春耕少，孤城夜漏闲。\n往时边有警，征马去无还。\n自顷方从化，年来亦款关。\n颇能贪汉布，但未脱金镮。\n何足争强弱，吾民尽玉颜。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%88%8E%E5%B7%9E_%28%E8%98%87%E8%BB%BE%29","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_008","title":"舟中听大人弹琴","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_04_rongzhou_yibin","location_text":"戎州至泸州舟中","summary":"舟中听父亲苏洵弹琴，写父子同行中的文艺生活。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"弹琴江浦夜漏水，敛衽窃听独激昂。\n风松瀑布已清绝，更爱玉佩声琅珰。\n自从郑卫乱雅乐，古器残缺世已忘。\n千家寥落独琴在，有如老仙不死阅兴亡。\n世人不容独反古，强以新曲求铿锵。\n微音淡弄忽变转，数声浮脆如笙簧。\n无情枯木今尚尔，何况古意堕渺茫。\n江空月出人响绝，夜阑更请弹文王。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%88%9F%E4%B8%AD%E8%81%BD%E5%A4%A7%E4%BA%BA%E5%BD%88%E7%90%B4","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_009","title":"泊南井口期任遵圣长官到晚不及见复来","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_04_rongzhou_yibin","location_text":"南井口，今地待核","summary":"停舟候任遵圣未遇，写行旅中的约会与错过。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"江上有微径，深榛烟雨埋。\n崎岖欲取别，不见又重来。\n下马未及语，固已慰长怀。\n江湖涉浩渺，安得与之偕。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%B3%8A%E5%8D%97%E7%89%9B%E5%8F%A3%E6%9C%9F%E4%BB%BB%E9%81%B5%E8%81%96%E9%95%B7%E5%AE%98%E5%88%B0%E6%99%9A%E4%B8%8D%E5%8F%8A%E8%A6%8B%E5%BE%A9%E4%BE%86","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_010","title":"过安乐山闻山上木叶有文如道士篆符云此山乃张道陵所寓二首 其一","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_06_luzhou_anleshan","location_text":"泸州安乐山","summary":"过张道陵传说地，回应山叶符文的神异传闻。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"天师化去知何在，玉印相传世共珍。\n故国子孙今尚死，满山秋叶岂能神。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E9%81%8E%E5%AE%89%E6%A8%82%E5%B1%B1%E8%81%9E%E5%B1%B1%E4%B8%8A%E6%9C%A8%E8%91%89%E6%9C%89%E6%96%87%E5%A6%82%E9%81%93%E5%A3%AB%E7%AF%86%E7%AC%A6%E4%BA%91%E6%AD%A4%E5%B1%B1%E4%B9%83%E5%BC%B5%E9%81%93%E9%99%B5%E6%89%80%E5%AF%93%E4%BA%8C%E9%A6%96","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_011","title":"过安乐山闻山上木叶有文如道士篆符云此山乃张道陵所寓二首 其二","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_06_luzhou_anleshan","location_text":"泸州安乐山","summary":"同题第二首，带有对神怪传说的怀疑和调侃。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"真人已不死，外慕堕空虚。\n犹馀好名意，满树写天书。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E9%81%8E%E5%AE%89%E6%A8%82%E5%B1%B1%E8%81%9E%E5%B1%B1%E4%B8%8A%E6%9C%A8%E8%91%89%E6%9C%89%E6%96%87%E5%A6%82%E9%81%93%E5%A3%AB%E7%AF%86%E7%AC%A6%E4%BA%91%E6%AD%A4%E5%B1%B1%E4%B9%83%E5%BC%B5%E9%81%93%E9%99%B5%E6%89%80%E5%AF%93%E4%BA%8C%E9%A6%96","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_012","title":"渝州寄王道矩","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_06_luzhou_anleshan","location_text":"渝州，今重庆","summary":"到渝州后寄友人王道矩，兼写旅况。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"曾闻五月到渝州，水拍长亭砌下流。\n惟有梦魂长缭绕，共论唐史更绸缪。\n舟经故国岁时改，霜落寒江波浪收。\n归梦不成冬夜永，厌闻船上报更筹。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%B8%9D%E5%B7%9E%E5%AF%84%E7%8E%8B%E9%81%93%E7%9F%A9","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_013","title":"江上看山","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_07_chuanjiang_mountains","location_text":"川江舟中","summary":"舟行看山，写群山在船行视角中如走马奔变。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"船上看山如走马，倏忽过去数百群。\n前山槎牙忽变态，后岭杂沓如惊奔。\n仰看微径斜缭绕，上有行人高缥渺。\n舟中举手欲与言，孤帆南去如飞鸟。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%B1%9F%E4%B8%8A%E7%9C%8B%E5%B1%B1_%28%E8%98%87%E8%BB%BE%29","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_014","title":"涪州得山胡次子由韵","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_07_chuanjiang_mountains","location_text":"涪州，今重庆涪陵一带","summary":"得山胡，次苏辙韵，行旅饮食和兄弟唱和。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"终日锁筠笼，回头惜翠茸。\n谁知声𠵾𠵾，亦自意重重。\n夜宿烟生浦，朝鸣日上峰。\n故巢何足恋，鹰隼岂能容。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%B6%AA%E5%B7%9E%E5%BE%97%E5%B1%B1%E8%83%A1%EF%BC%88%E5%96%84%E9%B3%B4%EF%BC%8C%E5%87%BA%E9%BB%94%E4%B8%AD%EF%BC%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_015","title":"留题仙都观","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_07_chuanjiang_mountains","location_text":"仙都观，今地待核","summary":"题道观，延续沿途道教遗迹书写。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"山前江水流浩浩，山上苍苍松柏老。\n舟中行客去纷纷，古今换易如秋草。\n空山楼观何峥嵘，真人王远阴长生。\n飞符御气朝百灵，悟道不复诵《黄庭》。\n龙车虎驾来下迎，去如旋风抟紫清。\n真人厌世不回顾，世间生死如朝暮。\n学仙度世岂无人，餐霞绝粒长辛苦。\n安得独从逍遥君，泠然乘风驾浮云，超世无有我独行。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E7%95%99%E9%A1%8C%E4%BB%99%E9%83%BD%E8%A7%80","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_016","title":"江上值雪效欧阳体限不以盐玉鹤鹭絮蝶飞舞之类为比仍不使皓白洁素等字次子由韵","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十月小寒前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_08_chuanjiang_snow","location_text":"川江舟中","summary":"江上遇雪，兄弟学欧阳体并自设禁字，属于文字训练。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"缩颈夜眠如冻龟，雪来惟有客先知。\n江边晓起浩无际，树杪风多寒更吹。\n青山有似少年子，一夕变尽沧浪髭。\n方知阳气在流水，沙上盈尺江无澌。\n随风颠倒纷不择，下满坑谷高陵危。\n江空野阔落不见，入户但觉轻丝丝。\n沾掌细看若刻镂，岂有一一天工为。\n霍然一挥遍九野，吁此权柄谁执持。\n世间苦乐知有几，今我幸免沾肤肌。\n山夫只见压樵担，岂知带酒飘歌儿。\n天王临轩喜有麦，宰相献寿嘉及时。\n冻吟书生笔欲折，夜织贫女寒无帏。\n高人著履踏冷冽，飘拂巾帽真仙姿。\n野僧斫路出门去，寒液满鼻清淋漓。\n洒袍入袖湿靴底，亦有执板趋阶墀。\n舟中行客何所爱，愿得猎骑当风披。\n草中咻咻有寒兔，孤隼下击千夫驰。\n敲冰煮鹿最可乐，我虽不饮强倒卮。\n楚人自古好弋猎，谁能往者我欲随。\n纷纭旋转从满面，马上操笔为赋之。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%B1%9F%E4%B8%8A%E5%80%BC%E9%9B%AA%E6%95%88%E6%AD%90%E9%99%BD%E9%AB%94%E9%99%90%E4%B8%8D%E4%BB%A5%E9%B9%BD%E7%8E%89%E9%B6%B4%E9%B7%BA%E7%B5%AE%E8%9D%B6%E9%A3%9B%E8%88%9E%E4%B9%8B%E9%A1%9E%E7%82%BA%E6%AF%94%E4%BB%8D%E4%B8%8D%E4%BD%BF%E7%9A%93%E7%99%BD%E6%BD%94%E7%B4%A0%E7%AD%89%E5%AD%97","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_017","title":"屈原塔","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十一月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_09_zhongzhou_to_kuizhou","location_text":"忠州 / 南宾一带","summary":"访屈原遗迹，写忠愤与乡俗祭吊。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"楚人悲屈原，千岁意未歇。\n精魂飘何处，父老空哽咽。\n至今沧江上，投饭救饥渴。\n遗风成竞渡，哀叫楚山裂。\n屈原古壮士，就死意甚烈。\n世俗安得知，眷眷不忍决。\n南宾旧属楚，山上有遗塔。\n应是奉佛人，恐子就沦灭。\n此事虽无凭，此意固已切。\n古人谁不死，何必较考折。\n名声实无穷，富贵亦暂热。\n大夫知此理，所以持死节。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E5%B1%88%E5%8E%9F%E5%A1%94%EF%BC%88%E5%9C%A8%E5%BF%A0%E5%B7%9E%EF%BC%8C%E5%8E%9F%E4%B8%8D%E7%95%B6%E6%9C%89%E5%A1%94%E6%96%BC%E6%AD%A4%EF%BC%8C%E6%84%8F%E8%80%85%E5%BE%8C%E4%BA%BA%E8%BF%BD%E6%80%9D%EF%BC%8C%E6%95%85%E7%82%BA%E4%BD%9C%E4%B9%8B%EF%BC%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_018","title":"望夫台","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十一月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_09_zhongzhou_to_kuizhou","location_text":"三峡沿线，今地待核","summary":"过望夫台，借江岸孤石写等待与过客。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"山头孤石远亭亭，江转船回石似屏。\n可怜千古长如昨，船去船来自不停。\n浩浩长江赴沧海，纷纷过客似浮萍。\n谁能坐待山月出，照见寒影高伶俜。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%9C%9B%E5%A4%AB%E8%87%BA%EF%BC%88%E5%9C%A8%E5%BF%A0%E5%B7%9E%E5%8D%97%E6%95%B8%E5%8D%81%E9%87%8C%EF%BC%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_019","title":"竹枝歌","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十一月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_09_zhongzhou_to_kuizhou","location_text":"三峡 / 楚地沿江","summary":"仿民歌体写楚地风俗和山民疾苦。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"．《竹枝歌》本楚声，幽怨恻怛，若有所深悲者。\n岂亦往者之所见有足怨者欤？夫伤二妃而哀屈原，思怀王而怜项羽，此亦楚人之意相传而然者。\n且其山川风俗鄙野勤苦之态，固已见于前人之作与今子由之诗。\n故特缘楚人畴昔之意，为一篇九章，以补其所未道者。\n苍梧山高湘水深，中原北望度千岑。\n帝子南游飘不返，惟有苍苍枫桂林。\n枫叶萧萧桂叶碧，万里远来超莫及。\n乘龙上天去无踪，草木无情空寄泣。\n水滨击鼓何喧阗，相将扣水求屈原。\n屈原已死今千载，满船哀唱似当年。\n海滨长鲸径千尺，食人为粮安可入。\n招君不归海水深，海鱼岂解哀忠直。\n吁嗟忠直死无人，可惜怀王西入秦。\n秦关已闭无归日，章华不复见车轮。\n君王去时箫鼓咽，父老送君车轴折。\n千里逃归迷故乡，南公哀痛弹长铗。\n三户亡秦信不虚，一朝兵起尽欢呼。\n当时项羽年最少，提剑本是耕田夫。\n横行天下竟何事，弃马乌江自垂涕。\n项王已死无故人，首入汉庭身委地。\n富贵荣华岂足多，至今唯有冢嵯峨。\n故国凄凉人事改，楚乡千古为悲歌。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E7%AB%B9%E6%9E%9D%E6%AD%8C%EF%BC%88%E4%B8%A6%E6%95%98%EF%BC%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_020","title":"过木枥观","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十一月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_09_zhongzhou_to_kuizhou","location_text":"木枥观，今地待核","summary":"过许逊斩蛟等道教传说地，写遗迹与神话。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"石壁高千尺，微踪远欲无。\n飞檐如剑寺，〈（出剑门东，望上寺宇仿佛可见。\n）〉古柏似仙都。\n许子尝高遁，行舟悔不迂。\n斩蛟闻猛烈，提剑想崎岖。\n寂寞棺犹在，修崇世已愚。\n隐居人不识，化去俗争吁。\n洞府烟霞远，人间爪发枯。\n飘飘乘倒景，谁复顾遗躯。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E9%81%8E%E6%9C%A8%E6%AB%AA%E8%A7%80","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_021","title":"八阵碛","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十一月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_09_zhongzhou_to_kuizhou","location_text":"鱼复 / 夔州一带","summary":"登览诸葛亮八阵图遗迹，怀古论兵。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"平沙何茫茫，仿佛见石蕝。\n纵横满江上，岁岁沙水啮。\n孔明死已久，谁复辨行列。\n神兵非学到，自古不留诀。\n至人已心悟，后世徒妄说。\n自从汉道衰，蜂起尽奸杰。\n英雄不相下，祸难久连结。\n驱民市无烟，战野江流血。\n万人赌一掷，杀尽如沃雪。\n不为久远计，草草常无法。\n孔明最后起，意欲扫群孽。\n崎岖事节制，隐忍久不决。\n志大遂成迂，岁月去如瞥。\n六师纷未整，一旦英气折。\n惟馀八阵图，千古壮夔峡。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E5%85%AB%E9%99%A3%E7%A3%A7_%28%E8%98%87%E8%BB%BE%29","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_022","title":"诸葛盐井","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十一月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_09_zhongzhou_to_kuizhou","location_text":"夔州一带","summary":"观诸葛盐井，借物理奇异发议论。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"〈（井有十四，自山下至山上，其十三井常空，盛夏水涨，则盐泉迤逦迁去，常去于江水之所不及。\n）〉\n五行水本咸，安择江与井。\n如何不相入，此意复谁省。\n人心固难足，物理偶相逞。\n犹嫌取未多，井上无闲绠。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%AB%B8%E8%91%9B%E9%B9%BD%E4%BA%95","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_023","title":"白帝庙","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十一月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_10_kuizhou_qutang","location_text":"白帝城，今重庆奉节","summary":"吊刘备、公孙述相关遗迹，写蜀汉兴亡。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"朔风催入峡，惨惨去何之。\n共指苍山路，来朝白帝祠。\n荒城秋草满，古树野藤垂。\n浩荡荆江远，凄凉蜀客悲。\n迟回问风俗，涕泗悯兴衰。\n故国依然在，遗民岂复知。\n一方称警跸，万乘拥旌旗。\n远略初吞汉，雄心岂在夔。\n崎岖来野庙，闵默愧常时。\n破甑蒸山麦，长歌唱竹枝。\n荆邯真壮士，吴柱本经师。\n失计虽无及，图王固已奇。\n犹余帝王号，皎皎在门楣。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E7%99%BD%E5%B8%9D%E5%BB%9F","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_024","title":"入峡","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十一月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_10_kuizhou_qutang","location_text":"夔门 / 瞿塘峡","summary":"入三峡，写山逼水、水势反激和舟行危险。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"自昔怀幽赏，今兹得纵探。\n长江连楚蜀，万派泻东南。\n合水来如电，黔波绿似蓝。\n馀流细不数，远势竞相参。\n入峡初无路，连山忽似龛。\n萦纡收浩渺，蹙缩作渊潭。\n风过如呼吸，云生似吐含。\n坠崖鸣窣窣，垂蔓绿毵毵。\n冷翠多崖竹，孤生有石楠。\n飞泉飘乱雪，怪石走惊骖。\n绝涧知深浅，樵童忽两三。\n人烟偶逢郭，沙岸可乘篮。\n野戍荒州县，邦君古子男。\n放衙鸣晚鼓，留客荐霜柑。\n闻道黄精草，丛生绿玉篸。\n尽应充食饮，不见有彭聃。\n气候冬犹暖，星河夜半涵。\n遗民悲昶衍，〈（孟昶从此入觐，王衍亦蜀主。）〉旧俗接鱼蚕。\n版屋漫无瓦，岩居窄似庵。\n伐薪常冒崄，得米不盈甔。\n叹息生何陋，劬劳不自惭。\n叶舟轻远溯，大浪固尝谙。\n矍铄空相视，呕哑莫与谈。\n蛮荒安可驻，幽邃信难妉。\n独爱孤栖鹘，高超百尺岚。\n横飞应自得，远飏似无贪。\n振翮游霄汉，无心顾雀鹌。\n尘劳世方病，局促我何堪。\n尽解林泉好，多为富贵酣。\n试看飞鸟乐，高遁此心甘。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E5%85%A5%E5%B3%BD_%28%E8%98%87%E8%BB%BE%29","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_025","title":"巫山","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十一月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_12_wushan_wuxia","location_text":"巫山、巫峡","summary":"写巫山险秀、神女传说和人对山水的震动。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"瞿塘迤逦尽，巫峡峥嵘起。\n连峰稍可怪，石色变苍翠。\n天工运神巧，渐欲作奇伟。\n坱轧势方深，结构意未遂。\n旁观不暇瞬，步步造幽邃。\n苍崖忽相逼，绝壁凛可悸。\n仰观八九顶，俊爽凌颢气。\n晃荡天宇高，崩腾江水沸。\n孤超兀不让，直拔勇无畏。\n攀缘见神宇，憩坐就石位。\n巉巉隔江波，一一问庙吏。\n遥观神女石，绰约诚有以。\n俯首见斜鬟，拖霞弄修帔。\n人心随物变，远觉含深意。\n野老笑吾旁，少年尝屡至。\n去随猿猱上，反以绳索试。\n石笋倚孤峰，突兀殊不类。\n世人喜神怪，论说惊幼稚。\n楚赋亦虚传，神仙安有是。\n次问扫坛竹，云此今尚尔。\n翠叶纷下垂，婆娑绿凤尾。\n风来自偃仰，若为神物使。\n绝顶有三碑，诘曲古篆字。\n老人那解读，偶见不能记。\n穷探到峰背，采斫黄杨子。\n黄杨生石上，坚瘦纹如绮。\n贪心去不顾，涧谷千寻缒。\n山高虎狼绝，深入坦无忌。\n洪濛草树密，葱茜云霞腻。\n石窦有洪泉，甘滑如流髓。\n终朝自盥漱，冷冽清心胃。\n浣衣挂树梢，磨斧就石鼻。\n徘徊云日晚，归意念城市。\n不到今十年，衰老筋力惫。\n当时伐残木，牙蘖已如臂。\n忽闻老人说，终日为叹喟。\n神仙固有之，难在忘势利。\n贫贱尔何爱，弃去如脱屣。\n嗟尔若无还，绝粮应不死。","text_scope":"full_page","text_source_label":"诗歌库《苏轼诗全集》","text_source_url":"https://www.shigeku.org/xlib/lingshidao/gushi/sushi3.htm","text_status":"local","text_status_note":"公开文本已接入；此条为补充来源，必须与可靠点校本复核"},{"work_id":"nanxing_work_026","title":"巫山庙上下数十里有乌鸢无数取食於行舟之上舟人以神之故亦不敢害","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十一月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_12_wushan_wuxia","location_text":"巫山庙上下","summary":"见乌鸢随舟取食，因神庙禁忌无人伤害。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"群飞来去噪行人，得食无忧便可驯。\n江上饥乌无足怪，野鹰何事亦频频。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E5%B7%AB%E5%B1%B1%E5%BB%9F%E4%B8%8A%E4%B8%8B%E6%95%B8%E5%8D%81%E9%87%8C%E6%9C%89%E7%83%8F%E9%B3%B6%E7%84%A1%E6%95%B8%E5%8F%96%E9%A3%9F%E6%96%BC%E8%A1%8C%E8%88%9F%E4%B9%8B%E4%B8%8A%E8%88%9F%E4%BA%BA%E7%A5%9E%E4%B9%8B%E6%95%85%E4%BA%A6%E4%B8%8D%E6%95%A2%E5%AE%B3","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_027","title":"神女庙","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十一月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_12_wushan_wuxia","location_text":"巫山神女庙","summary":"访神女庙，写神话、山川和庙祀。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"大江从西来，上有千仞山。\n江山自环拥，恢诡富神奸。\n深渊鼍鳖横〈（去声）〉，巨壑蛇龙顽。\n旌阳斩长蛟，雷雨移苍湾。\n蜀守降老蹇，至今带连环。\n纵横若无主，荡逸侵人寰。\n上帝降瑶姬，来处荆巫间。\n神仙岂在猛，玉座幽且闲。\n飘萧驾风驭，弭节朝天关。\n倏忽巡四方，不知道里艰。\n古妆具法服，邃殿罗烟鬟。\n百神自奔走，杂沓来趋班。\n云兴灵怪聚，云散鬼神还。\n茫茫夜潭静，皎皎秋月弯。\n还应摇玉佩，来听水潺潺。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E7%A5%9E%E5%A5%B3%E5%BB%9F","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_028","title":"过巴东县不泊闻颇有莱公遗迹","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十一月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_12_wushan_wuxia","location_text":"巴东","summary":"舟过不泊，听闻寇准遗迹，借地怀人。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"莱公昔未遇，寂寞在巴东。\n闻道山中树，犹余手种松。\n江山养豪俊，礼数困英雄。\n执版迎官长，趋尘拜下风。\n当年谁刺史，应未识三公。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E9%81%8E%E5%B7%B4%E6%9D%B1%E7%B8%A3%E4%B8%8D%E6%B3%8A%E8%81%9E%E9%A0%97%E6%9C%89%E8%90%8A%E5%85%AC%E9%81%BA%E8%B7%A1","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_029","title":"昭君村","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十一月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_13_xintan","location_text":"归州 / 兴山一带","summary":"过王昭君故里，写远嫁、乡国与命运反覆。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"昭君本楚人，艳色照江水。\n楚人不敢娶，谓是汉.mw-parser-output .variant-text{color:light-dark(black,white);border-bottom:1px dotted red;background:light-dark(linen,#311);cursor:pointer;position:relative}.mw-parser-output .variant-tooltip{display:none;position:absolute;bottom:100%;left:50%;transform:translateX(-50%);background:#333;color:#fff;padding:3px 8px;border-radius:4px;white-space:nowrap;font-size:0.9em;z-index:100}.mw-parser-output .variant-text:hover .variant-tooltip,.mw-parser-output .variant-text:focus .variant-tooltip,.mw-parser-output .variant-text:active .variant-tooltip{display:block}妃一作“家”子。\n谁知去乡国，万里为胡鬼。\n人言生女作门楣，昭君当时忧色衰。\n古来人事尽如此，反复纵横安可知。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%98%AD%E5%90%9B%E6%9D%91_%28%E8%98%87%E8%BB%BE%29","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_030","title":"新滩","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十一月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_13_xintan","location_text":"归州新滩","summary":"写新滩险急、白浪暗石和舟行惊惧。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"扁舟转山曲，未至已先惊。\n白浪横江起，槎牙似雪城。\n番番从高来，一一投涧坑。\n大鱼不能上，暴.mw-parser-output .variant-text{color:light-dark(black,white);border-bottom:1px dotted red;background:light-dark(linen,#311);cursor:pointer;position:relative}.mw-parser-output .variant-tooltip{display:none;position:absolute;bottom:100%;left:50%;transform:translateX(-50%);background:#333;color:#fff;padding:3px 8px;border-radius:4px;white-space:nowrap;font-size:0.9em;z-index:100}.mw-parser-output .variant-text:hover .variant-tooltip,.mw-parser-output .variant-text:focus .variant-tooltip,.mw-parser-output .variant-text:active .variant-tooltip{display:block}鬣一作“腮”滩下横。\n小鱼散复合，瀺灂如遭烹。\n鸬鹚不敢下，飞过两翅轻。\n白鹭夸瘦捷，插脚还欹倾。\n区区舟上人，薄技安敢呈。\n只应滩头庙，赖此牛酒盈。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%96%B0%E7%81%98","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_031","title":"新滩阻风","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十一月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_13_xintan","location_text":"归州新滩","summary":"大风雪阻舟三日，写寒江、滞留和旅途疲惫。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"北风吹寒江，来自两山口。\n初闻似摇扇，渐觉平沙走。\n飞云满岩谷，舞雪穿窗牖。\n滩下三日留，识尽滩〈（一作山）〉前叟。\n孤舟倦鸦轧，短缆困牵揉。\n尝闻不终朝，今此何其久。\n只应留远人，此意固亦厚。\n吾今幸无事，闭户为饮酒。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%96%B0%E7%81%98%E9%98%BB%E9%A2%A8","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_032","title":"黄牛庙","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月前","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_14_exit_gorges","location_text":"黄牛峡 / 黄牛庙","summary":"写黄牛神受祭与耕牛饥苦，带有强烈比兴。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"江边石壁高无路，上有黄牛不服箱。\n庙前行客拜且舞，击鼓吹箫屠白羊。\n山下耕牛苦硗确，两角磨崖四蹄湿。\n青刍半束长苦饥，仰看黄牛安可及。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E9%BB%83%E7%89%9B%E5%BB%9F","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_033","title":"虾蟆培","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月前","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_15_yiling","location_text":"虾蟆碚，峡州一带","summary":"写泉石形貌和水质，属于三峡地貌观察。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"蟆背似覆盂，蟆颐如偃月。\n谓是月中蟆，开口吐月液。\n根源来甚远，百尺苍崖裂。\n当时龙破山，此水随龙出。\n入江江水浊，犹作深碧色。\n禀受苦洁清，独与凡水隔。\n岂惟煮茶好，酿酒应无敌。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%9D%A6%E8%9F%86%E5%9F%B9","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_034","title":"出峡","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月前","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_15_yiling","location_text":"出三峡，夷陵附近","summary":"出峡后回顾前路，写由逼仄险境转入平旷。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"巴东三峡尽，旷望九江开。\n楚塞云中出，荆门水上来。\n鱼龙潜啸雨，凫雁动成雷。\n南国秋风晚，客思几悠哉。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E5%87%BA%E5%B3%BD","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_035","title":"游三游洞","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月前","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_15_yiling","location_text":"夷陵三游洞","summary":"游三游洞，先为亭吏留三绝句。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"冻雨霏霏半成雪，游人屦冻苍苔滑。不辞携被岩底眠，洞口云深夜无月。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E9%81%8A%E4%B8%89%E9%81%8A%E6%B4%9E","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_036","title":"游洞之日有亭吏乞诗既为留三绝句於洞之石壁明日至峡州吏又至意若未足乃复以此诗授之","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月前","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_15_yiling","location_text":"夷陵 / 峡州三游洞","summary":"亭吏再求诗，补成长篇，写洞穴、古俗和游兴。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"一径绕山翠，萦纡去似蛇。\n忽惊溪水急，争看洞门呀。\n滑磴攀秋蔓，飞桥踏古槎。\n三扉迎北吹，一穴向西斜。\n叹息烟云去，追思岁月遐。\n唐人昔未到，古俗此为家。\n洞暖无风雪，山深富鹿豭。\n相逢衣尽草，环坐髻应髽。\n灶突依岩墨，尊罍就石洼。\n洪荒无传记，想像在羲娲。\n此事今安有，遗踪我独嗟。\n山翁劝留句，强为写槎牙。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E9%81%8A%E4%B8%89%E9%81%8A%E6%B4%9E%E9%81%8A%E6%B4%9E%E4%B9%8B%E6%97%A5%E6%9C%89%E4%BA%AD%E5%90%8F%E4%B9%9E%E8%A9%A9%E6%97%A2%E7%82%BA%E7%95%99%E4%B8%89%E7%B5%95%E5%8F%A5%E6%96%BC%E6%B4%9E%E4%B9%8B%E7%9F%B3%E5%A3%81%E6%98%8E%E6%97%A5%E8%87%B3%E5%B3%BD%E5%B7%9E%E5%90%8F%E5%8F%88%E8%87%B3%E6%84%8F%E8%8B%A5%E6%9C%AA%E8%B6%B3%E4%B9%83%E5%BE%A9%E4%BB%A5%E6%AD%A4%E8%A9%A9%E6%8E%88%E4%B9%8B","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_037","title":"寄题清溪寺","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月前","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_15_yiling","location_text":"峡州清溪寺","summary":"题鬼谷子故居相关寺院，借纵横家发议论。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"口舌安足恃，韩非死说难。\n自知不可用，鬼谷乃真奸。\n遗书今未亡，小数不足观。\n秦仪固新学，见利不知患。\n嗟时无桓文，使彼二子颠。\n死败无足怪，夫子固使然。\n君看巧更穷，不若愚自安。\n遗宫若有神，颔首然吾言。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E5%AF%84%E9%A1%8C%E6%B8%85%E6%BA%AA%E5%AF%BA%EF%BC%88%E5%9C%A8%E5%B3%BD%E5%B7%9E%EF%BC%8C%E9%AC%BC%E8%B0%B7%E5%AD%90%E4%B9%8B%E6%95%85%E5%B1%85%EF%BC%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_038","title":"留题峡州甘泉寺","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月前","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_15_yiling","location_text":"峡州甘泉寺","summary":"题寺泉与村落，写山寺清泉和地方风俗。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"轻舟横江来，吊古悲纯孝。\n逶迤寻远迹，婉娈见遗貌。\n清泉不可挹，涸尽空石窖。\n古人飘何之，惟有风竹闹。\n行行玩村落，户户悬网罩。\n民风坦和平，开户夜无钞。\n丛林富笋茹，平野绝虎豹。\n嗟哉此乐乡，毋乃姜子教。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E7%95%99%E9%A1%8C%E5%B3%BD%E5%B7%9E%E7%94%98%E6%B3%89%E5%AF%BA%EF%BC%88%E5%A7%9C%E8%A9%A9%E6%95%85%E5%B1%85%EF%BC%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_039","title":"夷陵县欧阳永叔至喜堂","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月前","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_15_yiling","location_text":"夷陵至喜堂","summary":"访欧阳修贬居旧迹，写对欧阳修的敬仰和政治感受。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"夷陵虽小邑，自古控荆吴。\n形胜今无用，英雄久已无。\n谁知有文伯，远谪自王都。\n人去年年改，堂倾岁岁扶。\n追思犹咎吕，感叹亦怜朱。\n〈（时朱太守为公筑此堂。）〉\n旧种孤楠老，新霜一橘枯。\n清篇留峡洞，醉墨写邦图。\n〈（三游洞有诗，《夷陵图》后有留题处。）〉\n故老问行客，长官今白须。\n著书多念虑，许国减欢娱。\n寄语公知否，还须数倒壶。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E5%A4%B7%E9%99%B5%E7%B8%A3%E6%AD%90%E9%99%BD%E6%B0%B8%E5%8F%94%E8%87%B3%E5%96%9C%E5%A0%82","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_040","title":"息壤诗","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_17_jingzhou_new_year","location_text":"荆州 / 江陵一带","summary":"访禹迹“息壤”相关古迹，借神话地理怀古。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"《淮南子》曰：鲧湮洪水，盗帝之息壤，帝使祝融杀之于羽渊。\n今荆州南门外，有状若屋宇陷入地中，而犹见其脊者。\n旁有石记，云不可犯。\n畚锸所及，辄复如故。\n又颇以致雷雨，岁大旱，屡发有应。\n予感之，乃为作诗。\n其辞曰：\n帝息此壤，以藩幽台。\n有神司之，随取而培。\n帝敕下民，无取或开。\n惟帝不言，以雷以雨。\n惟民知之，幸帝之恕。\n帝茫不知，谁敢以告。\n帝怒不常，下土是震。\n使民前知，是役于民。\n无是坟者，谁取谁予。\n惟其的之，是以射之。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%81%AF%E5%A3%A4%E8%A9%A9%EF%BC%88%E4%B8%A6%E5%BC%95%EF%BC%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_041","title":"渚宫","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_17_jingzhou_new_year","location_text":"荆州","summary":"写楚王渚宫旧迹，进入楚地兴亡主题。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"渚宫寂寞依古郢，楚地荒茫非故基。\n二王台阁已卤莽，[1]何况远问纵横时。\n楚王猎罢击灵鼓，猛士操舟张水嬉。\n钓鱼不复数鱼鳖，大鼎千石烹蛟螭。\n当时郢人架宫殿，意思绝妙般与倕。\n飞楼百尺照湖水，上有燕赵千峨眉。\n临风扬扬意自得，长使宋玉作楚词。\n秦兵西来取钟簴，故宫禾黍秋离离。\n千年壮观不可复，今之存者盖已卑。\n池空野迥楼阁小，惟有深竹藏狐狸。\n台中绛帐谁复见，台下野.mw-parser-output .variant-text{color:light-dark(black,white);border-bottom:1px dotted red;background:light-dark(linen,#311);cursor:pointer;position:relative}.mw-parser-output .variant-tooltip{display:none;position:absolute;bottom:100%;left:50%;transform:translateX(-50%);background:#333;color:#fff;padding:3px 8px;border-radius:4px;white-space:nowrap;font-size:0.9em;z-index:100}.mw-parser-output .variant-text:hover .variant-tooltip,.mw-parser-output .variant-text:focus .variant-tooltip,.mw-parser-output .variant-text:active .variant-tooltip{display:block}水一作“鸭”浮清漪。\n绿窗朱户春昼闭，想见深屋弹朱丝。\n腐儒亦解爱声色，何用白首谈孔姬。\n沙泉半涸草堂在，破窗无纸风飔飔。\n陈公踪迹最未远，七瑞寥落今何之。\n百年人事知几变，直恐荒废成空陂。\n谁能为我访遗迹，草中应有湘东碑。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%B8%9A%E5%AE%AE","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_042","title":"荆州十首 其一","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月-1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_17_jingzhou_new_year","location_text":"荆州","summary":"荆州度岁期间组诗，写出峡后江汉平川与古城。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"游人出三峡，楚地尽平川。\n北客随南贾，吴樯间蜀船。\n江侵平野断，风卷白沙旋。\n欲问兴亡意，重城自古坚。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%8D%86%E5%B7%9E%E5%8D%81%E9%A6%96","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_043","title":"荆州十首 其二","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月-1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_17_jingzhou_new_year","location_text":"荆州","summary":"同组，写荆州风土、历史或旅怀。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"南方旧战国，惨淡意犹存。\n慷慨因刘表，凄凉为屈原。\n废城犹带井，古姓聚成村。\n亦解观形胜，升平不敢论。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%8D%86%E5%B7%9E%E5%8D%81%E9%A6%96","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_044","title":"荆州十首 其三","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月-1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_17_jingzhou_new_year","location_text":"荆州","summary":"同组，写荆州风土、历史或旅怀。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"楚地阔无边，苍茫万顷连。\n耕牛未尝汗，投种去如捐。\n农事谁当劝，民愚亦可怜。\n平生事游惰，那得怨凶年。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%8D%86%E5%B7%9E%E5%8D%81%E9%A6%96","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_045","title":"荆州十首 其四","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月-1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_17_jingzhou_new_year","location_text":"荆州","summary":"同组，写荆州风土、历史或旅怀。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"朱槛城东角，高王此望沙。\n江山非一国，烽火畏三巴。\n战骨沦秋草，危楼倚断霞。\n百年豪杰尽，扰扰见鱼虾。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%8D%86%E5%B7%9E%E5%8D%81%E9%A6%96","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_046","title":"荆州十首 其五","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月-1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_17_jingzhou_new_year","location_text":"荆州","summary":"同组，写荆州风土、历史或旅怀。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"沙头烟漠漠，来往厌喧卑。\n野市分獐闹，官帆过渡迟。\n游人多问卜，伧叟尽携龟。\n日暮江天静，无人唱楚辞。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%8D%86%E5%B7%9E%E5%8D%81%E9%A6%96","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_047","title":"荆州十首 其六","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月-1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_17_jingzhou_new_year","location_text":"荆州","summary":"同组，写荆州人物和入京前的政治提醒。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"太守王夫子，山东老俊髦。\n壮年闻猛烈，白首见雄豪。\n食雁君应厌，驱车我正劳。\n中书有安石，慎勿赋离骚。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%8D%86%E5%B7%9E%E5%8D%81%E9%A6%96","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_048","title":"荆州十首 其七","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月-1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_17_jingzhou_new_year","location_text":"荆州","summary":"同组，写岁末风雪、爆竹驱傩和客中年节。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"残腊多风雪，荆人重岁时。\n客心何草草，里巷自嬉嬉。\n爆竹惊邻鬼，驱傩逐小儿。\n故人应念我，相望各天涯。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%8D%86%E5%B7%9E%E5%8D%81%E9%A6%96","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_049","title":"荆州十首 其八","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月-1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_17_jingzhou_new_year","location_text":"荆州","summary":"同组，写江鱼物产和饮食场景。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"江水深成窟，潜鱼大似犀。\n赤鳞如琥珀，老枕胜玻璃。\n上客举雕俎，佳人摇翠篦。\n登疱更作器，何以免屠刲。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%8D%86%E5%B7%9E%E5%8D%81%E9%A6%96","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_050","title":"荆州十首 其九","author_ids":["su_shi"],"genre":"诗","year":1059,"time_text":"1059 十二月-1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_17_jingzhou_new_year","location_text":"荆州","summary":"同组，借北雁南来写旅人感触。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"北雁来南国，依依似旅人。\n纵横遭折翼，感恻为沾巾。\n平日谁能挹，高飞不可驯。\n故人持赠我，三嗅若为珍。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%8D%86%E5%B7%9E%E5%8D%81%E9%A6%96","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_051","title":"荆州十首 其一○","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月初","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_17_jingzhou_new_year","location_text":"荆州将行","summary":"写柳门京国道，回望荆楚、北趋许邓。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"柳门京国道，驱马及春阳。\n野火烧枯草，东风动绿芒。\n北行运许邓，南去极衡湘。\n楚境横天下，怀王信弱王。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%8D%86%E5%B7%9E%E5%8D%81%E9%A6%96","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_052","title":"荆门惠泉","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_18_jingzhou_departure","location_text":"荆门 / 荆门山一带，待核","summary":"写惠泉水脉，兼有山水考察意味。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"泉源从高来，走下随石脉。\n纷纷白沫乱，隐隐苍崖坼。\n萦回成曲沼，清澈见肝膈。\n众泻为长溪，奔驶荡蛙蝈。\n初开不容椀，渐去已如帛。\n传闻此山中，神物懒遭谪。\n不能致雷雨，滟滟吐寒碧。\n遂令山前人，千古灌稻麦。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%8D%8A%E9%96%80%E6%83%A0%E6%B3%89_%28%E8%98%87%E8%BB%BE%29","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_053","title":"次韵答荆门张都官维见和惠泉诗","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月前后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_18_jingzhou_departure","location_text":"荆门 / 荆门山一带，待核","summary":"张维和《惠泉诗》，苏轼次韵答之。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"楚人少井饮，地气常不泄。\n蓄之为惠泉，坌若有所折。\n泉源本无情，岂问浊与澈。\n贪愚彼二水，终古耻莫雪。\n只应所处然，遂使语异别。\n泉傍地平衍，泉上山𫶇嵲。\n君子慎所居，此义安可缺。\n古人贵言赠，敢用况高节。\n不为冬霜干，肯畏夏日裂。\n泠泠但不已，海远要当彻。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%AC%A1%E9%9F%BB%E7%AD%94%E8%8D%8A%E9%96%80%E5%BC%B5%E9%83%BD%E5%AE%98%E7%B6%AD%E8%A6%8B%E5%92%8C%E6%83%A0%E6%B3%89%E8%A9%A9","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_054","title":"浰阳早发","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_19_xiangyang","location_text":"浰阳，今地待核","summary":"荆州北上后早发行路，写入世与退缩的矛盾。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"富贵本先定，世人自荣枯。\n嚣嚣好名心，嗟我岂独无。\n不能便退缩，但使进少徐。\n我行念西国，已分田园芜。\n南来竟何事，碌碌随商车。\n自进茍无补，乃是懒且愚。\n人生重意气，出处夫岂徒。\n永怀江阳叟，种藕春满湖。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%B5%B0%E9%99%BD%E6%97%A9%E7%99%BC_%28%E8%98%87%E8%BB%BE%29","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_055","title":"夜行观星","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_18_jingzhou_departure","location_text":"荆襄陆路","summary":"夜行途中观星，写行旅夜色和天象。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"天高夜气严，列宿森就位。\n大星光相射，小星闹若沸。\n天人不相干，嗟彼本何事。\n世俗强指摘，一一立名字。\n南箕与北斗，乃是家人器。\n天亦岂有之，无乃遂自谓。\n迫观知何如，远想偶有以。\n茫茫不可晓，使我长叹喟。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E5%A4%9C%E8%A1%8C%E8%A7%80%E6%98%9F","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_056","title":"汉水","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_19_xiangyang","location_text":"汉水","summary":"渡汉水至襄阳，写水势和北上路程。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"舍棹忽逾月，沙尘困远行。\n襄阳逢汉水，偶似蜀江清。\n蜀江固浩荡，中有蛟与鲸。\n汉水亦云广，欲涉安敢轻。\n文王化南国，游女俨如卿。\n洲中浣纱子，环珮锵锵鸣。\n古风随世变，寒水空泠泠。\n过之不敢慢，伫立整冠缨。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%BC%A2%E6%B0%B4","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_057","title":"襄阳古乐府三首 野鹰来","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_19_xiangyang","location_text":"襄阳","summary":"古乐府之一，借野鹰意象写襄阳风物或怀古。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"野鹰来，万山下，荒山无食鹰苦饥，飞来为尔系彩丝。\n北原有兔老且白，年年养子秋食菽。\n我欲系之不可得，年深兔老鹰力弱。\n野鹰来，城东有台高崔巍。\n台中公子著皮袖，东望万里心悠哉。\n心悠哉，鹰何在。\n嗟尔公子归无劳，使鹰可呼亦凡曹，天阴月黑狐夜嗥。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%A5%84%E9%98%B3%E4%B9%90%E5%BA%9C%E4%B8%89%E7%AF%87%C2%B7%E9%87%8E%E9%B9%B0%E6%9D%A5","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_058","title":"襄阳古乐府三首 上堵吟","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_19_xiangyang","location_text":"襄阳 / 上堵，待核","summary":"古乐府之一，题涉襄阳地方旧曲或地名。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"台上有客吟秋风，悲声萧散飘入宫。\n台边游女来窃听，欲学声同意不同。\n君悲竟何事，千里金城两稚子。\n白马为塞凤为关，山川无人空且闲。\n我悲亦何苦，江水冬更深，鳊鱼冷难捕。\n悠悠江上听歌人，不知我意徒悲辛。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%A5%84%E9%98%B3%E4%B9%90%E5%BA%9C%E4%B8%89%E7%AF%87%C2%B7%E4%B8%8A%E5%A0%B5%E5%90%9F","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_059","title":"襄阳古乐府三首 襄阳乐","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_19_xiangyang","location_text":"襄阳","summary":"古乐府之一，写襄阳地方声情。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"使君未来襄阳愁，提戈入市裹毡裘。\n自从毡裘南渡沔，襄阳无事多春游。\n襄阳春游乐何许，岘山之阳汉江浦。\n使君朱旆来翻翻，人道使君似羊杜。\n道边逢人问洛阳，中原苦战春田荒。\n北人闻道襄阳乐，目送飞鸿应断肠。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%A5%84%E9%98%B3%E4%B9%90%E5%BA%9C%E4%B8%89%E7%AF%87%C2%B7%E8%A5%84%E9%98%B3%E4%B9%90","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_060","title":"岘山","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_19_xiangyang","location_text":"襄阳岘山","summary":"登岘山，怀羊祜堕泪碑等旧迹。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"远客来自南，游尘昏岘首。\n过关无百步，旷荡吞楚薮。\n登高忽惆怅，千载意有偶。\n所忧谁复知，嗟我生苦后。\n团团山上桧，岁岁阅榆柳。\n大才固已殊，安得同永久。\n可怜山前客，倏忽星过溜。\n贤愚未及分，来者当自剖。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E5%B3%B4%E5%B1%B1","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_061","title":"万山","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_19_xiangyang","location_text":"襄阳万山","summary":"游万山潭，怀杜预等人物遗迹。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"万山临汉江，杰立与岘偶。\n杜公破三吴，磊落叔子后。\n当年爱山意，无乃求自附。\n自比诚不惭，山水亦奇秀。\n羊公苟有知，当为颔其首。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%90%AC%E5%B1%B1","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_062","title":"隆中","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_19_xiangyang","location_text":"隆中","summary":"访诸葛亮草庐，写蜀客对武侯遗迹的感动。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"诸葛来西国，千年爱未衰。\n今朝游故里，蜀客不胜悲。\n谁言襄阳野，生此万乘师。\n山中有遗貌，矫矫龙之姿。\n龙蟠山水秀，龙去渊潭移。\n空馀蜿蜒迹，使我寒涕垂。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E9%9A%86%E4%B8%AD","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_063","title":"竹叶酒","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_19_xiangyang","location_text":"襄阳 / 宜城一带","summary":"题当地竹叶酒，借酒写风土与古意。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"楚人汲汉水，酿酒古宜城。\n春风吹酒熟，犹似汉江清。\n耆旧何人在，丘坟应已平。\n惟余竹叶在，留此千古情。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E7%AB%B9%E8%91%89%E9%85%92","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_064","title":"鯿鱼","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_19_xiangyang","location_text":"襄阳 / 汉水一带","summary":"写汉水鳊鱼，兼怀杜甫、孟浩然相关诗意。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"晓日照江水，游鱼似玉瓶。\n谁言解缩项，贪饵每遭烹。\n杜老当年意，临流忆孟生。\n吾今又悲子，辍筋涕纵横。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E9%AF%BF%E9%AD%9A","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_065","title":"食雉","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_18_jingzhou_departure","location_text":"陆行途中","summary":"食野雉，写旅途饮食与物命感。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"雄雉曳修尾，惊飞向日斜。\n空中纷格斗，彩羽落如花。\n喧呼勇不顾，投网谁复嗟。\n百钱得一双，新味时所佳。\n烹煎杂鸡鹜，爪距漫槎牙。\n谁知化为蜃，海上落飞鸦。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E9%A3%9F%E9%9B%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_066","title":"新渠诗 其一","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_20_tangzhou","location_text":"唐州","summary":"为赵尚宽修渠安民作组诗，首章写新渠来水。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"新渠之水，其来舒舒。\n溢流于野，至于通衢。\n渠成如神，民始不知。\n问谁为之，邦君赵侯。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%96%B0%E6%B8%A0%E8%A9%A9%EF%BC%88%E4%B8%A6%E6%95%98%EF%BC%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_067","title":"新渠诗 其二","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_20_tangzhou","location_text":"唐州","summary":"同组，写渠田灌溉。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"新渠之田，在渠左右。\n渠来奕奕，如赴如凑。\n如云斯积，如屋斯溜。\n嗟唐之人，始识秔稌。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%96%B0%E6%B8%A0%E8%A9%A9%EF%BC%88%E4%B8%A6%E6%95%98%EF%BC%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_068","title":"新渠诗 其三","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_20_tangzhou","location_text":"唐州","summary":"同组，写流民迁徙来耕。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"新渠之民，自淮及潭。\n挈其妇姑，或走而颠。\n王命赵侯，宥我新民。\n无与王事，以讫七年。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%96%B0%E6%B8%A0%E8%A9%A9%EF%BC%88%E4%B8%A6%E6%95%98%EF%BC%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_069","title":"新渠诗 其四","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_20_tangzhou","location_text":"唐州","summary":"同组，代官府招告新民。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"侯调新民，尔既来止。\n其归尔邑，告尔邻里。\n良田千万，尔择尔取。\n尔耕尔食，遂为尔有。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%96%B0%E6%B8%A0%E8%A9%A9%EF%BC%88%E4%B8%A6%E6%95%98%EF%BC%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_070","title":"新渠诗 其五","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 正月后","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_20_tangzhou","location_text":"唐州","summary":"同组，写新民筑室、定居和安土。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"筑室于唐，孔硕且坚。\n生为唐民，饱粥与𫗴。\n死葬于唐，祭有雉豚。\n天子有命，我惟尔安。","text_scope":"group_stanza","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%96%B0%E6%B8%A0%E8%A9%A9%EF%BC%88%E4%B8%A6%E6%95%98%EF%BC%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_071","title":"许州西湖","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 二月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_21_xuzhou","location_text":"许州","summary":"游许州西湖，想到城市欢游背后的田野饥荒。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"西湖小雨晴，滟滟春渠长。\n来从古城角，夜半传新响。\n使君欲春游，浚沼役千掌。\n纷纭具畚锸，闹若蚁运壤。\n夭桃弄春色，生意寒犹怏。\n惟有落残梅，标格若矜爽。\n游人坌已集，挈榼三且两。\n醉客卧道傍，扶起尚偃仰。\n池台信宏丽，贵与民同赏。\n但恐城市欢，不知田野怆。\n颍川七不登，野气长苍莽。\n谁知万里客，湖上独长想。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E8%A8%B1%E5%B7%9E%E8%A5%BF%E6%B9%96","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_072","title":"双鳬观","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 二月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_22_ruzhou","location_text":"汝州、颍川一带，待核","summary":"过神仙遗迹，写王乔双凫传说。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"王乔古仙子，时出观人寰。\n常为汉郎吏，厌世去无还。\n双凫偶为戏，聊以惊世顽。\n不然神仙迹，罗网安能攀。\n纷纷尘埃中，铜印纡青纶。\n安知无隐者，窃笑彼愚奸。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E9%9B%99%E9%B3%A7%E8%A7%80%EF%BC%88%E5%9C%A8%E8%91%89%E7%B8%A3%EF%BC%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_073","title":"颍大夫庙","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 二月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_22_ruzhou","location_text":"颍考叔庙，汝州一带","summary":"游颍考叔庙，写柔言感暴主的政治伦理。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"人情难强回，天性可微感。\n世人争曲直，苦语费摇撼。\n大夫言何柔，暴主意自惨。\n荒祠旁孤冢，古隧有残坎。\n千年惟茅焦，世亦贵其胆。\n不解此微言，脱衣徒勇敢。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%BD%81%E5%A4%A7%E5%A4%AB%E5%BB%9F%EF%BC%88%E6%BD%81%E8%80%83%E5%8F%94%E4%B9%9F%EF%BC%8C%E5%BB%9F%E5%9C%A8%E6%B1%9D%E5%B7%9E%E6%BD%81%E6%A9%8B%EF%BC%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_074","title":"阮籍啸台","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 二月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_23_weishi","location_text":"尉氏","summary":"登阮籍啸台，借竹林名士写乱世自存。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"阮生古狂达，遁世默无言。\n犹余胸中气，长啸独轩轩。\n高情遗万物，不与世俗论。\n登临偶自写，激越荡乾坤。\n醒为啸所发，饮为醉所昏。\n谁能与之较，乱世足自存。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E9%98%AE%E7%B1%8D%E5%98%AF%E8%87%BA%EF%BC%88%E5%9C%A8%E5%B0%89%E6%B0%8F%EF%BC%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_075","title":"大雪独留尉氏有客入驿呼与饮至醉诘旦客南去竟不知其谁","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 二月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_23_weishi","location_text":"尉氏驿所","summary":"大雪阻行，与陌生旅人痛饮，次日不知其姓名。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"古驿无人雪满庭，有客冒雪来自北。\n纷纷笠上已盈寸，下马登堂面苍黑。\n苦寒有酒不能饮，见之何必问相识。\n我酌徐徐不满觥，看客倒尽不留湿。\n千门昼闭行路绝，相与笑语不知夕。\n醉中不复问姓名，上马忽去横短策。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E5%A4%A7%E9%9B%AA%E7%8B%AC%E7%95%99%E5%B0%89%E6%B0%8F","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"},{"work_id":"nanxing_work_076","title":"朱亥墓","author_ids":["su_shi"],"genre":"诗","year":1060,"time_text":"1060 二月","journey_id":"nanxing_1059_1060","collection_id":"nanxing_ji","visit_id":"nanxing_24_bianjing","location_text":"大梁 / 汴京近郊","summary":"入京前后吊朱亥墓，怀信陵君门客与战国义侠。","source_note":"01 食蓼少年.md：苏轼南行诗作索引；地点与存佚仍需逐首核对。","text":"昔日朱公子，雄豪不可追。\n今来游故国，大冢屈称儿。\n平日轻公相，千金弃若遗。\n梁人不好事，名字寄当时。\n鲁史盗齐豹，求名谁复知。\n慎无怨世俗，犹不遭仲尼。","text_scope":"full_page","text_source_label":"维基文库《东坡全集》","text_source_url":"https://zh.wikisource.org/zh-hans/%E6%9C%B1%E4%BA%A5%E5%A2%93%EF%BC%88%E4%BF%97%E8%AC%82%E5%B1%A0%E5%85%92%E5%8E%9F%EF%BC%89","text_status":"local","text_status_note":"公开文本已接入，仍需与可靠点校本逐首校勘"}];
